        /// <param name="aiStandardId"></param>
        public void GetMinMaxDOBforStandard(int aiSchoolId, int aiAcademicYearId, int aiStandardId, out DateTime adtMinDOB, out DateTime adtMaxDOB)
        {
            adtMinDOB = DateTime.MinValue;
			adtMaxDOB = DateTime.MinValue;
			
			string sSelectStatement = "SELECT DOBMin,DOBMax " +
                                      "FROM AdmissionProcessDetails" +
                                      " WHERE School_ID = " + aiSchoolId +
                                      " AND Academic_Year_ID = " + aiAcademicYearId +
                                      " AND Standard_Id = " + aiStandardId;
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            using (SqlDataReader oDRMinMaxDate = oSQLServerDbUtility.ExecuteSqlStatementAndGetResults(sSelectStatement))
            {
                if (oDRMinMaxDate.Read())
                {
                    if (oDRMinMaxDate["DOBMin"] != DBNull.Value)
                        adtMinDOB = Convert.ToDateTime(oDRMinMaxDate["DOBMin"]);
                    if (oDRMinMaxDate["DOBMax"] != DBNull.Value)
                        adtMaxDOB = Convert.ToDateTime(oDRMinMaxDate["DOBMax"]);
                }
            }
        }

