        public DataTable GetStudentAdmissionStatus(int aiSchoolId, int iAdmissionId)
        {
            string sSelectStatement = " SELECT  Student_Admissions.IsAdmitted"+
                                    " , AdmissionProcessDetails.LottoryDate"+
                                    " , Student_Admissions.Student_Admission_Id"+
                                    " , Student_Admissions.Form_Number"+
                                    " , Student_Admissions.MobileNumber"+
                                    " , Student_Admissions.SelectedInLottery "+
                                    " , AdmissionProcessDetails.IsLotteryConfirmed " +
                                    " FROM         Student_Admissions INNER JOIN "+
                                          " AdmissionProcessDetails ON Student_Admissions.School_Id = AdmissionProcessDetails.School_ID "+
                                          " AND Student_Admissions.Acedemic_Year_Id = AdmissionProcessDetails.Academic_Year_ID "+
                                          " AND Student_Admissions.For_Standard = AdmissionProcessDetails.Standard_Id "+
                                    " WHERE     (Student_Admissions.IsAdmitted = 1) "+
                                    " AND (Student_Admissions.Student_Admission_Id = "+iAdmissionId+")"+
                                    " AND (Student_Admissions.School_Id  = " + aiSchoolId + ")";
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
                return oSQLServerDbUtility.ExecuteSqlStatementAndGetDataTable(sSelectStatement);
        }

        public static DataSet GetStandardAndLocations(int aiSchoolid, int aiAcademicYearId)
        {
            string sSelectStatement = " SELECT  " +
                                " school_id " +
                                " , original_standard_id " +
                                " , standard_id " +
                                " , standard_name " +
                            " FROM " +
                                 " standard_master " +
                            " WHERE " +
                                 " is_deleted = N'" + Constants.C_NO + "'" +
                                 " AND school_id = " + aiSchoolid +
                                 " AND academic_year_id = " + aiAcademicYearId +
                             " ORDER BY " +
                                  " original_standard_id;";

            if (aiSchoolid == Constants.SchoolId.PPS.ToInt())
            {
                sSelectStatement += "SELECT " +
                                   "LivingLocationId" +
                                   " , LivingLocationName" +
                                   " FROM " +
                                   "StudentLivingLocations" +
                                   " WHERE " +
                                   "SchoolId = " + aiSchoolid +
                                   " AND Is_Deleted = 'N'" +
                                   " AND LivingLocationId >= 14" +
                                   " ORDER BY " +
                                   "LivingLocationName;";
            }
            else
            {
                sSelectStatement += "SELECT " +
                                    "LivingLocationId" +
                                    " , LivingLocationName" +
                                    " FROM " +
                                    "StudentLivingLocations" +
                                    " WHERE " +
                                    "SchoolId = " + aiSchoolid +
                                    " AND Is_Deleted = 'N'" +
                                    " ORDER BY " +
                                    "LivingLocationName;";
            }

            sSelectStatement += "SELECT " +
                                "ResidenceTypeId " +
                                ", Name " +
                          " FROM" +
                                " ResidenceTypes " +
                                 " WHERE " +
                                 " Is_Deleted = 'N'" +
                                  " ORDER BY " +
                                  " Name ;";

            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
                return oSQLServerDbUtility.ExecuteSqlStatementAndGetDataSet(sSelectStatement);
        }

