        public bool IsDuplicateFormNumber(string asFormNo)
        {
            string sWhere = "";
            bool bFlag = true;
            string sSelectStatement = "SELECT COUNT(*)  " +
                                            " FROM " +
                                            " Student_Admissions " +
                                         " WHERE " +
                                            " Form_Number =N'" + StringUtility.ReplaceSingleQuoteInString(asFormNo, false) + "'" +
                                            " AND Is_Deleted = 0 " +
                                            sWhere;

            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                int i = oSQLServerDbUtility.PerformIntQueryOnSqlServer(sSelectStatement);
                if (i > 0)
                    bFlag = false;
            }
            return bFlag;
        }
        
