        public List<AdmissionStatus> GetAllAdmissionStatuses()
        {
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                string sSelectStatement = "SELECT Id" +
                                            ",Name" +
                                            " FROM " +
                                            "AdmissionStatuses WITH(NOLOCK)" +
                                            " WHERE " +
                                            "IsDeleted = 0";

                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteSqlStatementAndGetResults(sSelectStatement))
                {
                    List<AdmissionStatus> lstStatuses = new List<AdmissionStatus>();
                    while (oSqlDataReader.Read())
                        lstStatuses.Add(new AdmissionStatus { Id = Convert.ToInt32(oSqlDataReader["Id"]), Name = Convert.ToString(oSqlDataReader["Name"]) });
                    return lstStatuses;
                }
            }
        }

