        /// <summary>
        /// This method is used to return all admission status comments.
        /// </summary>
        /// <param name="aiStudentAdmissionId"></param>
        /// <returns></returns>
        public List<AdmissionStatusDetails> GetAllComments(int aiStudentAdmissionId, out AdmissionDetails aoAdmissionDetails)
        {
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", this.miSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("StudentAdmissionId", aiStudentAdmissionId, SqlDbType.Int);
                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetAdmissionStatusComments"))
                {
                    List<AdmissionStatusDetails> lstDetails = new List<AdmissionStatusDetails>();

                    aoAdmissionDetails = new AdmissionDetails();

                    if (oSqlDataReader.Read())
                    {
                        aoAdmissionDetails.StudentName = Convert.ToString(oSqlDataReader["StudentName"]);
                        aoAdmissionDetails.FormNumber = Convert.ToString(oSqlDataReader["FormNumber"]);
                        aoAdmissionDetails.CurrentStatus = Convert.ToString(oSqlDataReader["CurrentStatus"]);
                        aoAdmissionDetails.StatusId = Convert.ToInt32(oSqlDataReader["StatusId"]);

                        oSqlDataReader.NextResult();
                        while (oSqlDataReader.Read())
                        {
                            lstDetails.Add
                                (
                                    new AdmissionStatusDetails
                                    {
                                        Id = Convert.ToInt32(oSqlDataReader["Id"]),
                                        FollowUpDate = Convert.ToDateTime(oSqlDataReader["FollowUpDate"]),
                                        Date = Convert.ToDateTime(oSqlDataReader["Date"]),
                                        Comment = Convert.ToString(oSqlDataReader["Comment"]),
                                        UpdatedBy = Convert.ToString(oSqlDataReader["UserName"])
                                    }
                                );
                        }
                    }
                    return lstDetails;
                }
            }
        }

