                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetSingleStudentAdmissionDetails"))
                {
                    if (oSqlDataReader.HasRows && oSqlDataReader.Read())
