    public class StudentAdmissionsCollectionDC
    {

        #region " Data Members "

        private int miSchoolId;
        private int miAcadamicId;
        private int miStandardId;
        private int miInsertById;

        #endregion " Data Members "

        # region " Constructors "

        public StudentAdmissionsCollectionDC()
        {
        }

        public StudentAdmissionsCollectionDC(int aiSchoolId, int aiAcademicId, int aiStandardId, int aiInsertById)
        {
            miSchoolId = aiSchoolId;
            miAcadamicId = aiAcademicId;
            miStandardId = aiStandardId;
            miInsertById = aiInsertById;
        }

        # endregion " Constructors "

        #region " Public Methods "

        // This function is used to Fetch the StudentAdmissions Details
        public static DataSet FetchStudentAdmissionsDetails()
        {
            string sFetchStatement = "SELECT  * FROM Student_Admissions";
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
                return oSQLServerDbUtility.ExecuteSqlStatementAndGetDataSet(sFetchStatement);
        }

        public void InsertMultipleStudentAdmission(string asStudentDetails, string asParentDetails, string asParentInAssociationEvent, string asNetBankingDetails)
        {
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", miSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcadamicYearId", miAcadamicId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("StandardId", miStandardId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("InsertedById", miInsertById, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("StudentDetailsXML", asStudentDetails, SqlDbType.Xml);
                oSQLServerDbUtility.AddParameter("ParentDetailsXML", asParentDetails, SqlDbType.Xml);
                oSQLServerDbUtility.AddParameter("ParentInAssociationEventXML", asParentInAssociationEvent, SqlDbType.Xml);
                oSQLServerDbUtility.AddParameter("NetBankingDetailsXML", asNetBankingDetails, SqlDbType.Xml);

                oSQLServerDbUtility.ExecuteStoredProcedureOnServer("usp_AddMultpleNewStudentAdmissionDetails");
            }
        }

        public DataTable GetNewAdmissionListForImport()
        {
            string sSelectStatement = "SELECT " +
                                            "Form_Number, First_Name, Last_Name, DOB" +
                                      " FROM " +
                                            " Student_Admissions" +
                                      " WHERE " +
                                            " School_Id = " + miSchoolId +
                                            " AND Acedemic_Year_Id = " + miAcadamicId +
                                            " AND For_Standard = " + miStandardId +
                                            " AND IsAdmitted = 1 " +
                                            " AND Is_Deleted = 0";
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
                return oSQLServerDbUtility.ExecuteSqlStatementAndGetDataTable(sSelectStatement);
        }
        #endregion " Public Methods "
    }
